uniform vec3 uDarkColor, uLightColor;
uniform vec2 uSize, uResolution;
uniform vec2 uRocketUv;
uniform sampler2D tPerlin, tNoise, tMouse;
varying float vSeed, vRatio;
varying vec2 vUv;
varying vec3 vNormal;
