    vec2 ratioedUv = vec2(5.0, vRatio) * (vUv + vSeed * 0.1);
    vec2 resizedUv = uSize * ratioedUv;
    vec2 sUv = gl_FragCoord.xy / max(uResolution, vec2(1.0));
    float mouse = clamp(texture2D(tMouse, sUv + 0.1 * (texture2D(tNoise, 0.4 * resizedUv).g - 0.5)).r, 0.0, 1.0);
    float time = uTime * 0.5 / max(uSize.x, 0.0001);
    float strength = 1.0;
    vec2 dUv = vUv;
    dUv *= 1.0 + 0.03 * mouse;
    dUv += 0.05 * mouse;
    dUv.y += 0.3 * strength * (texture2D(tNoise, resizedUv * 0.2 + vec2(-0.004, -0.02) * time).r - 0.5);
    dUv.y -= 0.5 * strength * (texture2D(tNoise, resizedUv * 0.08 + vec2(0.005, 0.01) * time).r - 0.5);
    dUv.y *= 1.0 + 0.1 * strength * (texture2D(tPerlin, resizedUv * 0.5 - 0.01 * time).r - 0.5);
    float smoothness = smoothstep(0.4, 0.7, texture2D(tNoise, resizedUv * 0.08 + vec2(-0.08, -0.04) * time).r);
    float clouds = smoothstep(0.9 - 0.1 * smoothness, 0.7, dUv.y);
    clouds *= smoothstep(0.0, 0.2, dUv.y - 0.2 * smoothstep(0.4, 1.0, dUv.x));
  float alpha = clouds * smoothstep(1.0, 0.9, vUv.y) * smoothstep(0.0, 0.1, vUv.y) * smoothstep(0.0, 0.1, vUv.x) * smoothstep(1.0, 0.9, vUv.x);
  alpha += smoothstep(0.2, 0.3, vUv.y) * smoothstep(0.7, 0.6, vUv.y) * smoothstep(0.2, 0.3, vUv.x) * smoothstep(0.9, 0.8, vUv.x);
  alpha = min(1.0, alpha);
  float borderFadeX =
    smoothstep(0.0, 0.22, vUv.x) *
    smoothstep(0.0, 0.22, 1.0 - vUv.x);
  float borderFadeY =
    smoothstep(0.0, 0.18, vUv.y) *
    smoothstep(0.0, 0.18, 1.0 - vUv.y);
  vec2 radialUv = (vUv - 0.5) * vec2(1.18, 0.86);
