  float cloudDarkness = smoothstep(0.4, 1.0, dUv.y) + smoothstep(0.4, 0.0, dUv.y);
  vec3 normalDirection = normalize(vNormal);
  vec3 viewDirection = normalize(vViewDirection);
    float rim = pow(1.0 - clamp(dot(normalDirection, viewDirection), 0.0, 1.0), 2.4);
    vec3 color = mix(uDarkColor, uLightColor, clamp(cloudDarkness, 0.0, 1.0));
    color += uLightColor * 0.04 * rim * alpha;
    color = mix(color, uDarkColor, rocketHole * 0.18);

    float whiteText = smoothstep(2.2, 2.3, uChapter);
    color *= mix(vec3(1.0), vec3(0.8, 0.85, 0.87), whiteText);
    vec2 guillotineUv = vec2(uRatio, 1.0) * 0.4 * sUv;
    float guillotine = smoothstep(2.3, 2.2, uChapter - 0.3 * sUv.y + 0.1 * (texture2D(tNoise, guillotineUv + 0.02 * texture2D(tNoise, 4.0 * guillotineUv).r).r - 0.5));
    alpha *= guillotine;
    alpha *= smoothstep(1.0, 0.3, uTransition);
    alpha *= smoothstep(0.6, 0.96, abs(vNormal.b));
