```typescript
private static readonly LAYOUT: ReadonlyArray<readonly [number, number]> = [
  [-1, 2], [0, 2], [1, 2], [-0.5, 1], [0.5, 1],
  [-1, 0], [0, 0], [1, 0], [-0.5, -1], [0.5, -1],
  [-1, -2], [0, -2], [1, -2],
];

private _syncNozzleAngles(cfg: JetEngineResolvedConfig): void {
  const nr = cfg.nozzleRadius;
  const gridStepX = nr * Math.max(0.2, cfg.nozzleGapX);
  const gridStepZ = nr * Math.max(0.2, cfg.nozzleGapZ);
  const tipY = -(cfg.baseLength * 0.85);
  JetEngine.LAYOUT.forEach(([gx, gz], i) => {
    const eng = this._inner[i];
    if (!eng || (gx === 0 && gz === 0)) return;
    const pos = new THREE.Vector3(gx * gridStepX, 0, gz * gridStepZ);
    const dir = new THREE.Vector3(0, tipY, 0).sub(pos).normalize();
    eng.group.quaternion.setFromUnitVectors(new THREE.Vector3(0, -1, 0), dir);
  });
}
```

