uniform float uTime; uniform float uSeed;
uniform float uNoiseSpeedR; uniform float uNoiseSpeedL;
uniform float uTurbR; uniform float uTurbL;
varying vec2 vUv; varying float vNDot;
__NOISE_GLSL__
void main(){
  vUv = uv;
  float t = uv.y;
  float tipW = pow(t, 1.6);
  vec3 pos = position;
  float angle = atan(position.x, position.z) + uSeed;
  vec2 tUV = vec2(angle*0.5+0.5, t*3.0 - uTime*uNoiseSpeedR + uSeed);
  float rT = (fbm(tUV*1.5, 3) - 0.5) * uTurbR * tipW;
  pos.x += rT * sign(position.x + 0.001);
  pos.z += rT * sign(position.z + 0.001);
  vec2 lUV = vec2(angle*0.4+0.5, t*2.0 - uTime*uNoiseSpeedL + uSeed*0.7);
  float lT = (fbm(lUV*1.2, 3) - 0.5) * uTurbL * tipW;
  pos.y += lT;
  vec3 wn = normalize(normalMatrix * normal);
  vec3 vd = normalize(-vec3(modelViewMatrix * vec4(position, 1.)));
  vNDot = dot(wn, vd);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
}

