private _syncDynamicUniforms(cfg: JetEngineResolvedConfig): void {
  const inn = this._uInner;
  inn.noiseSpeedR.value = 2.8 * cfg.innerNoiseSpeed;
  inn.noiseSpeedL.value = 2.2 * cfg.innerNoiseSpeed;
  inn.turbR.value       = 0.1  * cfg.turbulence;
  inn.turbL.value       = 0.22 * cfg.turbulence;
  inn.fragSpeed1.value  = 7.0  * cfg.innerNoiseSpeed;
  inn.fragSpeed2.value  = 4.5  * cfg.innerNoiseSpeed;
  inn.colorTop.value.setRGB(...cfg.innerColor.top);
  inn.colorTip.value.setRGB(...cfg.innerColor.tip);
  const flash = cfg.innerColor.top.map((v) => Math.min(1, v + 0.2)) as RGB;
  inn.colorFlash.value.setRGB(...flash);

  const par = this._uParent;
  par.noiseSpeedR.value = 2.4 * cfg.parentNoiseSpeed;
  par.noiseSpeedL.value = 1.8 * cfg.parentNoiseSpeed;
  par.turbR.value       = 0.18 * cfg.turbulence;
  par.turbL.value       = 0.3  * cfg.turbulence;
  par.fragSpeed1.value  = 1.2  * cfg.parentNoiseSpeed;
  par.fragSpeed2.value  = 0.7  * cfg.parentNoiseSpeed;
  par.colorTop.value.setRGB(...cfg.parentColor.top);
  par.colorTip.value.setRGB(...cfg.parentColor.tip);
}

private _syncNozzleAngles(cfg: JetEngineResolvedConfig): void {
  const nr = cfg.nozzleRadius;
  const gridStepX = nr * Math.max(0.2, cfg.nozzleGapX);
  const gridStepZ = nr * Math.max(0.2, cfg.nozzleGapZ);
  const tipY = -(cfg.baseLength * 0.85);
  const down = new THREE.Vector3(0, -1, 0);
  JetEngine.LAYOUT.forEach(([gx, gz], i) => {
    const eng = this._inner[i];
    if (!eng || (gx === 0 && gz === 0)) return;
    const pos = new THREE.Vector3(gx * gridStepX, 0, gz * gridStepZ);
    const dir = new THREE.Vector3(0, tipY, 0).sub(pos).normalize();
    eng.group.quaternion.setFromUnitVectors(down, dir);
  });
}

